function lireCorps(req, limite = 10000) {
  return new Promise((ok, ko) => {
    let texte = "";
    req.on("data", m => {
      texte += m;
      if (texte.length > limite) {
        const e = new Error("corps trop volumineux");
        e.statut = 413;
        ko(e);
        req.removeAllListeners("data");
        req.resume();
      }
    });
    req.on("end", () => ok(texte));
    req.on("error", ko);
  });
}

